const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const R = nextInt();
    if (R === null) return;
    const N = nextInt();

    const minPrice = new Map();

    for (let i = 0; i < N; i++) {
        const t = nextInt();
        const p = nextInt();
        if (!minPrice.has(t) || p < minPrice.get(t)) {
            minPrice.set(t, p);
        }
    }

    const prices = Array.from(minPrice.values());
    prices.sort((a, b) => a - b);

    let count = 0;
    let currentMoney = R;

    for (let i = 0; i < prices.length; i++) {
        if (currentMoney >= prices[i]) {
            currentMoney -= prices[i];
            count++;
        } else {
            break;
        }
    }

    console.log(count);
}

main();
